def parse_headers(raw: str) -> dict[str, str]:
    result = {}
    for line in raw.split('\n'):
        if line.endswith('\r'):
            line = line[:-1]
        if not line.strip():
            continue
        if ':' not in line:
            raise ValueError(f"Header line without colon: {line!r}")
        name, value = line.split(':', 1)
        name = name.strip().lower()
        value = value.strip()
        if name in result:
            result[name] = result[name] + ', ' + value
        else:
            result[name] = value
    return result
```

