def compact(n: int) -> str:
    if n < 1000:
        return str(n)

    units = [
        (10**9, "bi"),
        (10**6, "mi"),
        (10**3, "mil"),
    ]

    for divisor, unit in units:
        if n >= divisor:
            break

    n10 = n * 10
    tenths = n10 // divisor
    if (n10 % divisor) * 2 >= divisor:
        tenths += 1

    if tenths == 10000:
        if unit == "mil":
            unit, tenths = "mi", 10
        elif unit == "mi":
            unit, tenths = "bi", 10

    whole, dec = divmod(tenths, 10)
    if dec:
        return f"{whole},{dec} {unit}"
    return f"{whole} {unit}"
