def reached(value, threshold) -> bool:
    from decimal import Decimal

    if isinstance(value, bool) or isinstance(threshold, bool):
        raise TypeError("value and threshold must be int, float, or Decimal, not bool")
    if not isinstance(value, (int, float, Decimal)) or not isinstance(threshold, (int, float, Decimal)):
        raise TypeError("value and threshold must be int, float, or Decimal")

    def to_decimal(x):
        if isinstance(x, Decimal):
            return x
        if isinstance(x, int):
            return Decimal(x)
        return Decimal(str(x))

    return to_decimal(value) >= to_decimal(threshold)
