import heapq

def build_order(deps: dict[str, list[str]]) -> list[str]:
    all_nodes = set(deps)
    for dependencies in deps.values():
        all_nodes.update(dependencies)

    graph = {node: [] for node in all_nodes}
    indegree = {node: 0 for node in all_nodes}

    for item, dependencies in deps.items():
        for dep in set(dependencies):
            graph[dep].append(item)
            indegree[item] += 1

    ready = [node for node in all_nodes if indegree[node] == 0]
    heapq.heapify(ready)

    order = []

    while ready:
        node = heapq.heappop(ready)
        order.append(node)

        for dependent in graph[node]:
            indegree[dependent] -= 1
            if indegree[dependent] == 0:
                heapq.heappush(ready, dependent)

    if len(order) != len(all_nodes):
        raise ValueError("cycle detected")

    return order
```

