def wrap(text: str, width: int) -> list[str]:
    words = text.split()
    if not words:
        return []

    if width <= 0:
        raise ValueError("width must be positive")

    lines = []
    current = ""

    for word in words:
        if len(word) > width:
            if current:
                lines.append(current)
                current = ""

            remaining = word
            while len(remaining) > width:
                lines.append(remaining[:width])
                remaining = remaining[width:]

            current = remaining
        else:
            if not current:
                current = word
            elif len(current) + 1 + len(word) <= width:
                current += " " + word
            else:
                lines.append(current)
                current = word

    if current:
        lines.append(current)

    return lines
