def latest_by_key(records: list[dict], key: str) -> list[dict]:
    from datetime import datetime, timezone

    selected: dict = {}

    for record in records:
        value = record[key]
        updated_at = record["updated_at"].strip()

        if updated_at.endswith(("Z", "z")):
            updated_at = updated_at[:-1] + "+00:00"

        parsed = datetime.fromisoformat(updated_at)
        if parsed.tzinfo is None:
            parsed = parsed.replace(tzinfo=timezone.utc)

        if value not in selected:
            selected[value] = (record, parsed)
        else:
            _, latest_parsed = selected[value]
            if parsed >= latest_parsed:
                selected[value] = (record, parsed)

    return [record for record, _ in selected.values()]
```

