import ipaddress

def ip_allowed(ip: str, networks: list[str]) -> bool:
    if not isinstance(ip, str):
        return False

    try:
        addr = ipaddress.ip_address(ip)
    except ValueError:
        return False

    if isinstance(addr, ipaddress.IPv6Address) and addr.ipv4_mapped is not None:
        addr = addr.ipv4_mapped

    parsed_networks = []
    for net_str in networks:
        if not isinstance(net_str, str):
            raise ValueError(f"Invalid network: {net_str!r}")
        try:
            net = ipaddress.ip_network(net_str, strict=False)
        except ValueError as exc:
            raise ValueError(f"Invalid network: {net_str!r}") from exc
        parsed_networks.append(net)

    for net in parsed_networks:
        if addr in net:
            return True
    return False
