from decimal import Decimal, InvalidOperation

def parse_brl(s: str) -> Decimal:
    if not isinstance(s, str):
        raise ValueError

    s = s.strip()
    if not s:
        raise ValueError

    negative = False

    if s[0] == '(' or s[-1] == ')':
        if not (s[0] == '(' and s[-1] == ')'):
            raise ValueError
        negative = True
        s = s[1:-1].strip()
        if not s:
            raise ValueError
    elif s[0] == '-':
        negative = True
        s = s[1:].strip()
        if not s:
            raise ValueError

    if s.startswith('R$'):
        s = s[2:].strip()
        if not s:
            raise ValueError

    if ',' in s:
        if s.count(',') != 1:
            raise ValueError
        integer_part, cents = s.split(',')
        if len(cents) != 2 or not cents.isdigit():
            raise ValueError
    else:
        integer_part = s
        cents = None

    if not integer_part:
        raise ValueError

    if '.' in integer_part:
        groups = integer_part.split('.')
        if any(not g.isdigit() for g in groups):
            raise ValueError
        if len(groups[0]) > 3 or any(len(g) != 3 for g in groups[1:]):
            raise ValueError
        number_str = ''.join(groups)
    else:
        if not integer_part.isdigit():
            raise ValueError
        number_str = integer_part

    result_str = f"{number_str}.{cents}" if cents is not None else number_str

    try:
        value = Decimal(result_str)
    except InvalidOperation:
        raise ValueError

    return -value if negative else value
