_LOG_RE = re.compile(r'^(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2},\d{3}) \[([^]]+)] (.*)$')


def parse_log(line: str) -> dict:
    match = _LOG_RE.match(line)
    if not match:
        raise ValueError(f"Invalid log line: {line!r}")

    timestamp_str, raw_level, rest = match.groups()

    try:
        ts = datetime.strptime(timestamp_str, '%Y-%m-%d %H:%M:%S,%f')
    except ValueError as exc:
        raise ValueError(f"Invalid timestamp in log line: {line!r}") from exc

    level = raw_level.strip().upper()
    if not level:
        raise ValueError(f"Invalid log level in line: {line!r}")
    if level == 'WARNING':
        level = 'WARN'

    if ': ' in rest:
        logger, msg = rest.split(': ', 1)
    else:
        logger, msg = rest, ''

    return {
        'ts': ts,
        'level': level,
        'logger': logger,
        'msg': msg,
    }
