import re

def parse_brl(s: str) -> Decimal:
    if not isinstance(s, str):
        raise ValueError

    s = s.strip()
    if not s:
        raise ValueError

    sign = 1
    if s.startswith('(') or s.endswith(')'):
        if not (s.startswith('(') and s.endswith(')')):
            raise ValueError
        sign = -1
        s = s[1:-1].strip()
    elif s.startswith('-'):
        sign = -1
        s = s[1:].strip()

    if s.startswith('R$'):
        s = s[2:].strip()

    pattern = r'(?:[0-9]+|[0-9]{1,3}(?:\.[0-9]{3})+)(?:,[0-9]{2})?'
    if not re.fullmatch(pattern, s):
        raise ValueError

    if ',' in s:
        int_part, cents = s.split(',', 1)
    else:
        int_part, cents = s, None

    int_part = int_part.replace('.', '')

    numeric = f"{int_part}.{cents}" if cents is not None else int_part
    value = Decimal(numeric)

    return -value if sign < 0 else value
