def compare_versions(a: str, b: str) -> int:
    def split_version(v: str):
        v = v.split('+', 1)[0]
        core, sep, pre = v.partition('-')
        return core, pre if sep else None

    def is_numeric(s: str) -> bool:
        return bool(s) and all('0' <= ch <= '9' for ch in s)

    def compare_identifier(x: str, y: str) -> int:
        x_num = is_numeric(x)
        y_num = is_numeric(y)

        if x_num and y_num:
            xi, yi = int(x), int(y)
            if xi < yi:
                return -1
            if xi > yi:
                return 1
            return 0

        if x_num:
            return -1
        if y_num:
            return 1

        if x == y:
            return 0
        return -1 if x < y else 1

    core_a, pre_a = split_version(a)
    core_b, pre_b = split_version(b)

    nums_a = [int(part) for part in core_a.split('.')]
    nums_b = [int(part) for part in core_b.split('.')]

    if nums_a != nums_b:
        return -1 if nums_a < nums_b else 1

    if pre_a is None and pre_b is None:
        return 0
    if pre_a is None:
        return 1
    if pre_b is None:
        return -1

    ids_a = pre_a.split('.')
    ids_b = pre_b.split('.')

    for x, y in zip(ids_a, ids_b):
        result = compare_identifier(x, y)
        if result:
            return result

    if len(ids_a) < len(ids_b):
        return -1
    if len(ids_a) > len(ids_b):
        return 1
    return 0
