import heapq


def build_order(deps: dict[str, list[str]]) -> list[str]:
    # Collect all items: keys plus items that appear only as dependencies
    items = set(deps)
    for ds in deps.values():
        items.update(ds)

    # Build reverse adjacency (dependency -> items depending on it) and indegrees
    dependents = {item: [] for item in items}
    indegree = {item: 0 for item in items}
    for item, ds in deps.items():
        for d in ds:
            dependents[d].append(item)
            indegree[item] += 1

    # Kahn's algorithm with a min-heap so ties break alphabetically
    heap = [item for item in items if indegree[item] == 0]
    heapq.heapify(heap)

    order = []
    while heap:
        item = heapq.heappop(heap)
        order.append(item)
        for nxt in dependents[item]:
            indegree[nxt] -= 1
            if indegree[nxt] == 0:
                heapq.heappush(heap, nxt)

    if len(order) != len(items):
        raise ValueError("Cycle detected in dependencies")

    return order
```

