import unicodedata


def sort_names(names: list[str]) -> list[str]:
    """Sort names for a phone book.

    Primary key: the name with accents removed, compared case-insensitively.
    Tie-break 1: accent-free names come before accented ones.
    Tie-break 2: the original strings, compared as-is.
    """

    def deaccent(s: str) -> str:
        return ''.join(
            ch for ch in unicodedata.normalize('NFD', s)
            if not unicodedata.combining(ch)
        )

    def key(name: str):
        plain = deaccent(name)
        return (plain.casefold(), plain != name, name)

    return sorted(names, key=key)
