def wrap(text: str, width: int) -> list[str]:
    words = text.split()
    if not words:
        return []
    if width < 1:
        raise ValueError("width must be at least 1")

    # Cut any word longer than width into chunks of width characters.
    tokens = []
    for word in words:
        tokens.extend(word[i:i + width] for i in range(0, len(word), width))

    # Greedily pack tokens into lines of at most width characters.
    lines = []
    current = ""
    for token in tokens:
        if not current:
            current = token
        elif len(current) + 1 + len(token) <= width:
            current += " " + token
        else:
            lines.append(current)
            current = token
    if current:
        lines.append(current)
    return lines
