from datetime import datetime, timezone


def latest_by_key(records: list[dict], key: str) -> list[dict]:
    def to_instant(record: dict) -> datetime:
        value = record["updated_at"]
        if value.endswith("Z"):
            value = value[:-1] + "+00:00"
        dt = datetime.fromisoformat(value)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        return dt

    best: dict = {}
    for record in records:
        k = record[key]
        ts = to_instant(record)
        # '>=' ensures that on an instant tie, the later record in the list wins.
        if k not in best or ts >= best[k][0]:
            best[k] = (ts, record)

    # Dicts preserve insertion order, so this yields first-appearance order.
    return [record for _, record in best.values()]
