from decimal import Decimal


def reached(value, threshold) -> bool:
    """Return True if value >= threshold.

    Numbers are compared as they are written: a float counts as its
    shortest decimal representation (so the float 0.7 is exactly 0.7).
    Accepts int, float and decimal.Decimal in any mix; raises TypeError
    for any other type, bool included.
    """

    def as_decimal(x):
        if isinstance(x, bool) or not isinstance(x, (int, float, Decimal)):
            raise TypeError(
                f"reached() arguments must be int, float or decimal.Decimal, "
                f"not {type(x).__name__}"
            )
        if isinstance(x, float):
            # repr() yields the shortest decimal string that round-trips
            # back to the same float, i.e. the number as it is written.
            return Decimal(repr(x))
        if isinstance(x, int):
            return Decimal(x)
        return x  # already a Decimal (immutable, safe to use directly)

    a = as_decimal(value)
    b = as_decimal(threshold)
    if a.is_nan() or b.is_nan():
        # Ordered Decimal comparisons would raise InvalidOperation on NaN;
        # follow float semantics instead: NaN never reaches a threshold.
        return False
    return a >= b
