def compare_versions(a: str, b: str) -> int:
    def cmp(x, y):
        return (x > y) - (x < y)

    def parse(v: str):
        v = v.split('+', 1)[0]           # build metadata is ignored
        core, _, pre = v.partition('-')  # first '-' starts the pre-release
        major, minor, patch = core.split('.')
        return (int(major), int(minor), int(patch)), (pre or None)

    def compare_prerelease(p1, p2):
        if p1 is None and p2 is None:
            return 0
        if p1 is None:
            return 1    # release is higher than any pre-release
        if p2 is None:
            return -1
        ids1, ids2 = p1.split('.'), p2.split('.')
        for x, y in zip(ids1, ids2):
            if x == y:
                continue
            if x.isdigit() and y.isdigit():
                return cmp(int(x), int(y))      # numeric compared as numbers
            if x.isdigit():
                return -1                        # numeric < alphanumeric
            if y.isdigit():
                return 1
            return cmp(x, y)                     # ASCII order
        return cmp(len(ids1), len(ids2))         # shorter list is lower

    core_a, pre_a = parse(a)
    core_b, pre_b = parse(b)
    result = cmp(core_a, core_b)
    if result != 0:
        return result
    return compare_prerelease(pre_a, pre_b)
