import re


def natural_sorted(names: list[str]) -> list[str]:
    def sort_key(name: str) -> list:
        # re.split with a capturing group alternates non-digit text (even
        # indices, possibly empty) and digit runs (odd indices), so equal
        # positions across keys always compare the same types. int() makes
        # digit runs compare numerically, so leading zeros don't matter.
