def wrap(text: str, width: int) -> list[str]:
    """Break text into lines of at most width characters.

    Words are separated by any whitespace and are never split, except a
    word longer than width, which is cut into pieces of width characters
    (the last piece may be shorter). Lines contain single spaces between
    words with no leading or trailing spaces. Text with no words yields [].
    """
    # Split into words on any whitespace; pre-cut any word longer than
    # width into pieces of exactly width characters.
    words = []
    for word in text.split():
        if len(word) <= width:
            words.append(word)
        else:
            for i in range(0, len(word), width):
                words.append(word[i:i + width])

    # Greedily pack words onto lines of at most width characters.
    lines = []
    current = ''
    for word in words:
        if not current:
            current = word
        elif len(current) + 1 + len(word) <= width:
            current += ' ' + word
        else:
            lines.append(current)
            current = word
    if current:
        lines.append(current)
    return lines
