import re


def natural_sorted(names: list[str]) -> list[str]:
    def key(name: str):
        chunks = []
        for index, part in enumerate(re.split(r'(\d+)', name)):
            if not part:
                continue
            if index % 2:  # odd indices are the captured digit runs
                # Compare as an integer so leading zeros don't matter
                # (e.g. 'img007' and 'img7' produce identical keys).
                chunks.append((0, int(part), ''))
            else:  # text runs compare case-insensitively
                chunks.append((1, 0, part.lower()))
        return tuple(chunks)

    # sorted() is stable, so names with equal keys keep their original order.
    return sorted(names, key=key)
