def set_ini_value(text: str, section: str, key: str, value: str) -> str:
    lines = text.splitlines(keepends=True)
    in_section = False
    section_found = False
    replaced = False

    for i, line in enumerate(lines):
        stripped = line.strip()

        # Blank lines and comments are never touched and never change state.
        if not stripped or stripped.startswith(';') or stripped.startswith('#'):
            continue

        # Section header line?
        if stripped.startswith('[') and stripped.endswith(']'):
            in_section = (stripped[1:-1].strip() == section)
            if in_section:
                section_found = True
            continue

        if not in_section or replaced:
            continue

        if '=' not in stripped:
            continue

        left = stripped.split('=', 1)[0].strip()
        if left == key:
            # Preserve the exact line ending of the original line.
            newline = line[len(line.rstrip('\r\n')):]
            lines[i] = f'{key} = {value}{newline}'
            replaced = True

    if not section_found:
        raise KeyError(f'section [{section}] not found')
    if not replaced:
        raise KeyError(f"key '{key}' not found in section [{section}]")

    return ''.join(lines)
