from copy import deepcopy


def deep_merge(base: dict, override: dict) -> dict:
    """Return a new dict merging ``override`` into ``base``.

    Rules:
      * Keys in ``override`` win over ``base``.
      * When a key's value is a dict in both inputs, the dicts are
        merged recursively (same rules apply at every level).
      * Lists and all other values are replaced wholesale, never merged.
      * An ``override`` value of ``None`` deletes the key from the result.
      * Neither input is modified, and the result shares no nested
        dict or list object with either input.
    """

    def merge(b: dict, o: dict) -> dict:
        out = {}
        # Keys from base: keep, overwrite, merge, or delete.
        for key, value in b.items():
            if key not in o:
                out[key] = value
                continue
            o_value = o[key]
            if o_value is None:
                continue  # explicit deletion
            if isinstance(value, dict) and isinstance(o_value, dict):
                out[key] = merge(value, o_value)
            else:
                out[key] = o_value  # replacement (lists, scalars, etc.)
        # Keys only in override: add unless explicitly deleted.
        for key, o_value in o.items():
            if key not in b and o_value is not None:
                out[key] = o_value
        return out

    # Deep-copy once at the end so no nested dict/list is shared with
    # either input (intra-structure aliasing is preserved).
    return deepcopy(merge(base, override))
