def allocate(total_cents: int, weights: list[int]) -> list[int]:
    if total_cents < 0:
        raise ValueError("total_cents cannot be negative")
    if not weights:
        raise ValueError("weights cannot be empty")
    if any(w < 0 for w in weights):
        raise ValueError("weights cannot contain negative values")
    if all(w == 0 for w in weights):
        raise ValueError("all weights cannot be zero")

    splits = []
    remainder = total_cents
    for w in weights:
        splits.append(remainder // w)
        remainder %= w

    # Distribute remainder to parts with largest remainder
    remainder_parts = sorted(
        [(i, remainder // w) for i, w in enumerate(weights)],
        key=lambda x: (-x[1], x[0])
    )
    for i, _ in remainder_parts:
        splits[i] += 1

    return splits
