from decimal import Decimal

def parse_brl(s: str) -> Decimal:
    s = s.strip()
    if not s:
        raise ValueError("Empty string")

    # Remove optional prefix and spaces
    s = s.replace('R$', '').replace(' ', '')

    # Handle negative signs
    if s.startswith('-'):
        sign = '-'
        s = s[1:]
    elif s.startswith('('):
        sign = '-'
        s = s[1:].rstrip(')')

    # Check for invalid characters
    if not s.replace('.', '').replace(',', '').isdigit():
        raise ValueError("Invalid characters in string")

    # Split into integer and cents parts
    if ',' in s:
        integer_part, cents_part = s.split(',', 1)
    else:
        integer_part = s
        cents_part = ''

    # Validate cents part
    if len(cents_part) != 2:
        raise ValueError("Cents part must be exactly 2 digits")

    # Process integer part
    if '.' in integer_part:
        if len(integer_part.split('.')[0]) != 3:
            raise ValueError("Integer part must be grouped in 3 digits with a dot")
        integer_part = integer_part.replace('.', '')
    else:
        if len(integer_part) > 3:
            raise ValueError("Integer part must be grouped in 3 digits or plain digits")

    # Combine parts
    amount = integer_part + cents_part
    return Decimal(sign + amount)
