def compact(n: int) -> str:
    if n == 0:
        return '0'

    scale = 1
    units = ['', 'mil', 'mi', 'bi']
    while n >= 1000 and scale < len(units) - 1:
        n /= 1000
        scale += 1

    rounded = round(n, 1)
    if rounded == int(rounded):
        rounded = int(rounded)

    if rounded == 1 and scale == 1:
        return f'1'
    elif rounded == 1 and scale == 2:
        return '1 mi'
    elif rounded == 1 and scale == 3:
        return '1 bi'

    return f'{rounded:.1f}'.rstrip('0').rstrip(',') + units[scale]
