from decimal import Decimal

def parse_brl(s: str) -> Decimal:
    s = s.strip()
    if not s:
        raise ValueError("Empty string")

    # Handle optional prefix and spaces
    if s.startswith(('R$', 'R$ ')):
        s = s[2:].strip()
    elif s.startswith('('):
        s = s[1:].strip()
        if not s.startswith('R$'):
            raise ValueError("Invalid parentheses format")
        s = s[2:].strip()
    elif s.startswith('-'):
        s = s[1:].strip()
        sign = -1
    else:
        sign = 1

    # Remove all non-digit characters except '.', ',', and '-'
    cleaned = []
    for c in s:
        if c in '0123456789.':
            cleaned.append(c)
        elif c == ',':
            cleaned.append('.')
        elif c == '-':
            cleaned.append(c)
        elif c == '(' or c == ')':
            raise ValueError("Invalid parentheses usage")
        else:
            raise ValueError("Invalid character in string")

    cleaned_str = ''.join(cleaned)

    # Handle integer part
    if '.' in cleaned_str:
        integer_part, fractional_part = cleaned_str.split('.', 1)
    else:
        integer_part = cleaned_str
        fractional_part = ''

    # Validate integer part
    if not integer_part:
        raise ValueError("Empty integer part")

    # Check for invalid grouping (dots not in groups of 3)
    if '.' in integer_part:
        parts = integer_part.split('.')
        if len(parts) != 2:
            raise ValueError("Invalid grouping in integer part")
        if len(parts[0]) != 3:
            raise ValueError("Invalid grouping in integer part")

    # Validate fractional part
    if ',' in cleaned_str:
        fractional_part = fractional_part.replace(',', '.')
        if len(fractional_part) != 2:
            raise ValueError("Invalid cents part")
    elif fractional_part and len(fractional_part) != 2:
        raise ValueError("Invalid cents part")

    # Combine parts
    if fractional_part:
        amount = sign * Decimal(f"{integer_part}.{fractional_part}")
    else:
        amount = sign * Decimal(integer_part)

    return amount
```

