def build_order(deps: dict[str, list[str]]) -> list[str]:
    in_degree = {item: 0 for item in deps}
    for item in deps:
        for dep in deps[item]:
            if dep not in in_degree:
                raise ValueError("Dependency not in graph")
            in_degree[dep] += 1

    queue = []
    for item in sorted(in_degree.keys()):
        if in_degree[item] == 0:
            queue.append(item)

    order = []
    while queue:
        current = min(queue)
        queue.remove(current)
        order.append(current)

        for neighbor in deps.get(current, []):
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    if len(order) != len(in_degree):
        raise ValueError("Cycle detected")

    return order
```

