def wrap(text: str, width: int) -> list[str]:
    if not text.strip():
        return []

    words = text.split()
    lines = []
    current_line = []
    current_length = 0

    for word in words:
        if current_length + len(word) <= width:
            current_line.append(word)
            current_length += len(word) + 1
        else:
            if current_line:
                lines.append(' '.join(current_line))
                current_line = [word]
                current_length = len(word)
            else:
                lines.append(word)
                current_length = len(word)

    if current_line:
        lines.append(' '.join(current_line))

    return lines
