    if total_cents < 0:
        raise ValueError("total_cents must be non-negative")
    if not weights:
        raise ValueError("weights list cannot be empty")
    if any(w < 0 for w in weights):
        raise ValueError("weights cannot contain negative values")
    if all(w == 0 for w in weights):
        raise ValueError("all weights must be non-zero")

    splits = []
    remainder = total_cents
    for w in weights:
        split = remainder // w
        splits.append(split)
        remainder -= split * w

    # Distribute remainder to parts with largest remainder
    remainder_parts = sorted(
        [(w, remainder // w) for w, split in zip(weights, splits)],
        key=lambda x: -x[1]
    )
    for w, _ in remainder_parts:
        splits[weights.index(w)] += 1

