from decimal import Decimal

def parse_brl(s: str) -> Decimal:
    s = s.strip()
    if not s:
        raise ValueError("Empty string")

    # Handle optional prefix and spaces
    if s.startswith(('R$', 'R$ ')):
        s = s[2:].strip()
    elif s.startswith('-R$'):
        s = s[3:].strip()
    elif s.startswith('('):
        s = s[1:].strip()
        if not s.endswith(')'):
            raise ValueError("Unclosed parentheses")
        s = s[:-1].strip()
        if s.startswith('-'):
            s = '-' + s[1:].strip()

    # Check for negative sign
    if s.startswith('-'):
        sign = '-'
        s = s[1:].strip()
    else:
        sign = ''

    # Parse the number part
    if ',' in s:
        integer_part, cents_part = s.split(',', 1)
        cents_part = cents_part.lstrip()
        if len(cents_part) != 2:
            raise ValueError("Cents must be exactly 2 digits")
    else:
        integer_part = s
        cents_part = '00'

    # Handle integer part with optional thousands separators
    if '.' in integer_part:
        if len(integer_part.split('.')[0]) != 3:
            raise ValueError("Thousands separator must be exactly 3 digits")
        integer_part = integer_part.split('.')[1]
    else:
        integer_part = integer_part.lstrip()

    if not integer_part.isdigit():
        raise ValueError("Invalid integer part")

    # Combine parts
    total = sign + integer_part + cents_part
    return Decimal(total)
