    b_parts = parse_version(b)

    release_a, numeric_pre_a, alphanumeric_pre_a, build_a = a_parts
    release_b, numeric_pre_b, alphanumeric_pre_b, build_b = b_parts

    # Compare release versions
    for ra, rb in zip(release_a, release_b):
        if ra < rb:
            return -1
        elif ra > rb:
            return 1

    if len(release_a) < len(release_b):
        return -1
    elif len(release_a) > len(release_b):
        return 1

    # Compare pre-release versions
    # Compare numeric parts first
    for na, nb in zip(numeric_pre_a, numeric_pre_b):
        if na < nb:
            return -1
        elif na > nb:
            return 1

    # Compare alphanumeric parts
    for a, b in zip(alphanumeric_pre_a, alphanumeric_pre_b):
        if a < b:
            return -1
        elif a > b:
            return 1

    # If all numeric and alphanumeric parts are equal, shorter pre-release is lower
    if len(numeric_pre_a) + len(alphanumeric_pre_a) < len(numeric_pre_b) + len(alphanumeric_pre_b):
        return -1
    elif len(numeric_pre_a) + len(alphanumeric_pre_a) > len(numeric_pre_b) + len(alphanumeric_pre_b):
        return 1

    # Compare build versions (ignored)
    return 0
```

