from datetime import datetime

def latest_by_key(records: list[dict], key: str) -> list[dict]:
    key_value_to_records = {}

    for record in records:
        value = record[key]
        if value not in key_value_to_records:
            key_value_to_records[value] = []
        key_value_to_records[value].append(record)

    latest_records = {}
    for value, records_list in key_value_to_records.items():
        latest_record = max(records_list, key=lambda r: datetime.fromisoformat(r['updated_at'].replace('Z', '+00:00')))
        latest_records[value] = latest_record

    return [latest_records[value] for value in key_value_to_records.keys() if value in latest_records]
```

